def L(title,objective,body,example,exercise,answer,points,checks,refs,thai):
 return dict(title=title,objectives=[objective],explanation=body.split('\n\n'),example=example,exercise=exercise,model_response=answer,key_points=points,checks=checks,references=refs,thai_summary=thai)
def Q(q,a,b,c,why):return dict(question=q,choices=[a,b,c],correct_answer=a,explanation=why)
