def metadata(cid,title,docid,refs,classification='General industry knowledge'):
 return dict(document_id=docid,course_id=cid,title=title,version='0.1.0',created_date=DATE,last_updated_date=DATE,author_source='AI-assisted instructional draft; source references attached',information_classification=classification,approval_status='Draft',responsible_reviewer='Company to designate',source_references=refs)

def dump(path,obj):
 path=ROOT/path;path.parent.mkdir(parents=True,exist_ok=True);path.write_text(json.dumps(obj,ensure_ascii=False,indent=2),encoding='utf-8')

def build():
 knowledge=[]
 for n,c in enumerate(COURSES,1):
  cid=f'AITS-C{n:02}';folder=f'course-{n:02}-{c["slug"]}';c.update(id=cid,folder=folder,metadata=metadata(cid,c['title'],cid,sorted({r for l in c['lessons'] for r in l['references']})),prerequisites=[] if n==1 else ['AITS-C01'],estimated_minutes=100,language='en',translation_status='Thai summaries only; AI translation pending native-speaker review',objectives=[l['objectives'][0] for l in c['lessons']])
  questions=[]
  for i,l in enumerate(c['lessons'],1):
   lid=f'{cid}-L{i:02}';l.update(id=lid,estimated_minutes=15,prerequisites=c['prerequisites'] if i==1 else [f'{cid}-L{i-1:02}'],summary=' '.join(l['key_points']),visual_resources=[f'{folder}/infographics/workflow.svg'],metadata=metadata(cid,l['title'],lid,l['references'],'Mixed; see references and labeled examples'))
   for j,q in enumerate(l['checks'],1):
    q.update(id=f'{lid}-Q{j}',related_lesson=lid,difficulty='beginner' if j<3 else 'intermediate',type='multiple_choice',source_references=l['references'],metadata=metadata(cid,q['question'],f'{lid}-Q{j}',l['references']))
    # Vary answer placement deterministically, preserving the answer text.
    shift=(i+j+n)%3;q['choices']=q['choices'][shift:]+q['choices'][:shift];questions.append(q)
   l['knowledge_checks']=[q['id'] for q in l.pop('checks')]
   dump(f'{folder}/lessons/{lid}.json',l)
   body=f'<h1>{html.escape(l["title"])}</h1><p><strong>{WARNING}</strong></p><p>Version 0.1.0 | {lid} | Draft | 15 minutes</p>'
   for title,parts in [('Learning objective',l['objectives']),('Explanation',l['explanation']),('Synthetic example',[l['example']]),('Practical exercise',[l['exercise']]),('Model response',[l['model_response']]),('Summary',[l['summary']]),('Thai summary — translation pending review',[l['thai_summary']]),('References',[r+': '+SOURCES[r][0]+' — '+SOURCES[r][1] for r in l['references']])]:
    body+='<h2>'+html.escape(title)+'</h2>'+''.join('<p>'+html.escape(p)+'</p>' for p in parts)
   l['html']=body;(ROOT/folder/'lessons'/f'{lid}.html').write_text('<!doctype html><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><style>body{max-width:780px;margin:32px auto;padding:0 20px;font:18px/1.65 Arial,sans-serif}h1,h2{line-height:1.25}strong{color:#C53130}</style>'+body,encoding='utf-8')
   knowledge.append(dict(topic=l['title'],question=l['objectives'][0],answer=' '.join(l['explanation']),source_document=l['references'],source_classification='Verified company information' if n==1 and i in [1,2] else 'Hypothetical examples' if n==1 and i==3 else 'General industry knowledge',applicable_role=c['roles'],approval_status='Draft',review_date=None,next_review_due='2027-02-09',related_course=cid,related_lesson=lid,authoritative_company_use=False,metadata=l['metadata']))
  statement=[
   'An unapproved sample lesson can establish official AITS policy.',
   'This training establishes the approved AITS grievance procedure.',
   'A completion report should disclose unresolved defects.',
   'Customer passwords belong in the ordinary handover report.',
   'A ping timeout alone proves a device is powered off.',
   'Sending an email always proves a task is complete.',
   'An AI practice score is official employee competency certification.'
  ][n-1]
  tf=questions[-1];tf.update(question=statement,type='true_false',choices=['True','False'],correct_answer='True' if n==3 else 'False')
  tf['metadata']['title']=statement
  if n==5:tf['explanation']='A timeout can reflect filtering or policy; compare other authorized service tests before deciding that a device is off.'
  c['assessments']=questions;c['scenarios']=[]
  for j,(title,role,problem,info,good,bad,consequence) in enumerate(c.pop('scenario_seeds'),1):
   sid=f'{cid}-S{j:02}'
   s=dict(id=sid,title=title,context='Synthetic classroom exercise; not an AITS procedure.',employee_role=role,problem_description=problem,available_information=[info],decision_points=['What would you check first, and why?','What requires confirmation or authorization?','What would you record and hand over?'],expected_actions=[good,'Record evidence, uncertainty and the next authorized action.'],appropriate_decisions=[good],inappropriate_decisions=[bad],consequences=consequence,evaluation_rubric=[dict(criterion='Evidence and scope',max_score=2,anchors={'0':'Makes unsupported assumptions','1':'Identifies some relevant facts','2':'Uses the available facts and names missing evidence'}),dict(criterion='Decision quality',max_score=2,anchors={'0':bad,'1':'Partially appropriate but misses a necessary check','2':good}),dict(criterion='Authority and safety',max_score=2,anchors={'0':'Acts beyond authority or creates exposure','1':'Recognizes a limit but gives no next action','2':'Pauses where necessary and seeks the correct authorized review'}),dict(criterion='Handover',max_score=2,anchors={'0':'No useful record','1':'Records symptom only','2':'Records result, uncertainty and next action'})],scoring='0–8 formative points; any unsafe or unauthorized action requires coaching regardless of total. Not competency certification.',source_references=['EX']+c['metadata']['source_references'],metadata=metadata(cid,title,sid,['EX'],'Hypothetical examples'))
   c['scenarios'].append(s)
  dump(f'{folder}/assessments/quiz.json',dict(metadata=metadata(cid,'Course practice assessment',cid+'-QUIZ',c['metadata']['source_references']),passing_threshold_percent=80,threshold_status='Proposed practice threshold; not company competency policy',questions=questions))
  dump(f'{folder}/scenarios/scenarios.json',c['scenarios'])
  dump(f'{folder}/course.json',c)
 dump('curriculum.json',dict(metadata=metadata('ALL','AITS review curriculum','AITS-CURRICULUM',list(SOURCES)),courses=COURSES))
 dump('knowledge-base/items.json',knowledge)
 dump('sources/inventory.json',[dict(id=k,title=v[0],url_or_path=v[1],classification=v[2],publication_or_access=v[3],scope_limit=v[4]) for k,v in SOURCES.items()])
 print(f'Generated {len(COURSES)} courses, {sum(len(c["lessons"]) for c in COURSES)} lessons, {sum(len(c["assessments"]) for c in COURSES)} questions and {sum(len(c["scenarios"]) for c in COURSES)} scenarios.')

if __name__=='__main__':build()
